glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 p = vec4(a_position, 1.0);
  #if USE_LOCAL
    p = cc_matWorld * p;
  #endif
  uv0 = a_texCoord;
  color = a_color;
  return cc_matViewProj * p;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
layout(std140) uniform HeroMotion {
  vec4 atlasRect;
  vec4 bodyMotion;
  vec4 armMotion;
  vec4 heroShape;
};
uniform sampler2D cc_spriteTexture;
vec4 frag () {
  vec2 p = (uv0 - atlasRect.xy) / atlasRect.zw;
  vec2 q = p;
  float upper = 1.0 - smoothstep(0.58, 0.90, p.y);
  q.x -= bodyMotion.x * upper;
  q.y += bodyMotion.y * upper;
  float chest = smoothstep(0.12, 0.32, p.y) * (1.0 - smoothstep(0.64, 0.9, p.y));
  q.y += bodyMotion.z * chest;
  float side = smoothstep(0.43, 0.66, p.x);
  float high = 1.0 - smoothstep(0.48, 0.70, p.y);
  float armWeight = mix(side * high, 1.0 - smoothstep(0.28, 0.52, p.y), heroShape.z);
  vec2 joint = heroShape.xy;
  vec2 d = q - joint;
  d.x *= heroShape.w;
  float a = -armMotion.x * armWeight;
  float co = cos(a), si = sin(a);
  q = joint + vec2((co * d.x - si * d.y) / heroShape.w, si * d.x + co * d.y);
  float edges = (1.0 - smoothstep(0.14, 0.38, p.x)) + smoothstep(0.68, 0.9, p.x);
  float hem = smoothstep(0.42, 0.65, p.y) * (1.0 - smoothstep(0.80, 0.90, p.y));
  q.x -= sin(p.y * 8.0 - armMotion.z * 2.2) * bodyMotion.w * edges * hem;
  if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return vec4(0.0);
  vec4 o = CCSampleWithAlphaSeparated(cc_spriteTexture, atlasRect.xy + q * atlasRect.zw);
  float crystal = smoothstep(0.68, 0.85, p.x) * (1.0 - smoothstep(0.13, 0.31, p.y));
  o.rgb *= 1.0 + armMotion.y * crystal;
  o *= color;
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

